import { useState, useEffect, useRef, useMemo } from "react";
import { supabase } from "./supabase";
import {
  Home, Package, ShoppingCart, List, Plus, Camera, Search,
  Trash2, Pencil, ArrowLeft, Loader2, AlertTriangle, Check,
  Minus, Printer, X, ImageOff, BarChart3, RefreshCcw, MessageSquare
} from "lucide-react";

const LOGO_DATA_URL = "data:image/png;base64,";

const FONT_IMPORT = `@import url('https://fonts.googleapis.com/css2?family=Public+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&display=swap');`;

const LOW_STOCK_DEFAULT = 5;

function uid() {
  return crypto.randomUUID();
}

function money(n) {
  const v = Number(n) || 0;
  return v.toLocaleString("es-AR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

async function resizeImage(file, maxDimension = 800, quality = 0.72) {
  if (!file || !file.type?.startsWith("image/")) {
    throw new Error("El archivo seleccionado no es una imagen");
  }

  // Evita intentar decodificar archivos desproporcionadamente grandes en móviles.
  if (file.size > 25 * 1024 * 1024) {
    throw new Error("La foto es demasiado pesada. Elegí una imagen de menos de 25 MB.");
  }

  const canvasToDataUrl = (source, sourceWidth, sourceHeight) => {
    const scale = Math.min(1, maxDimension / Math.max(sourceWidth, sourceHeight));
    const width = Math.max(1, Math.round(sourceWidth * scale));
    const height = Math.max(1, Math.round(sourceHeight * scale));
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d", { alpha: false });
    if (!ctx) throw new Error("No se pudo preparar la imagen");
    ctx.drawImage(source, 0, 0, width, height);
    const dataUrl = canvas.toDataURL("image/jpeg", quality);
    canvas.width = 1;
    canvas.height = 1;
    return dataUrl;
  };

  // Camino preferido en Android/iOS modernos: el navegador reduce durante la
  // decodificación y evita mantener una copia Base64 gigante de la foto original.
  if (typeof createImageBitmap === "function") {
    let bitmap;
    try {
      bitmap = await createImageBitmap(file, {
        resizeWidth: maxDimension,
        resizeQuality: "medium",
        imageOrientation: "from-image"
      });
      return canvasToDataUrl(bitmap, bitmap.width, bitmap.height);
    } catch (error) {
      console.warn("createImageBitmap no pudo procesar la foto; usando método alternativo", error);
    } finally {
      if (bitmap?.close) bitmap.close();
    }
  }

  const objectUrl = URL.createObjectURL(file);

try {
  const img = new Image();
  img.decoding = "async";

  await new Promise((resolve, reject) => {
    img.onload = resolve;
    img.onerror = () =>
      reject(new Error("No se pudo procesar la imagen"));
    img.src = objectUrl;
  });

  return canvasToDataUrl(
    img,
    img.naturalWidth || img.width,
    img.naturalHeight || img.height
  );
} finally {
  URL.revokeObjectURL(objectUrl);
}
}

async function matchProductByPhoto(targetDataUrl, candidates) {
  // En móviles evitamos serializar muchas fotos Base64 de una sola vez.
  // Se comparan en lotes pequeños para reducir los picos de memoria.
  const BATCH_SIZE = 1;
  const limited = candidates.slice(0, 30);

  let bestMatch = null;
let bestConfidence = 0;

for (let i = 0; i < limited.length; i += BATCH_SIZE) {
  const batch = limited.slice(i, i + BATCH_SIZE);

  const response = await fetch("/api/vision", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      action: "match",
      targetDataUrl,
     candidates: batch.map((p) => ({
  id: p.id,
  nombre: p.nombre,
  foto: p.foto,
  modelo: p.modelo || "",
  material: p.material || "",
  color: p.color || "",
  terminacion: p.terminacion || "",
  virola: p.virola || "",
  guarda: p.guarda || "",
  base: p.base || "",
  patas: p.patas || "",
  bolitas: p.bolitas || "",
  detalles: p.detalles || ""
})) 
    })
  });

  if (!response.ok) {
    throw new Error("No se pudo analizar la foto");
  }

  const data = await response.json();
  const confidence = Number(data.confidence || 0);

  if (data.productId && confidence > bestConfidence) {
    bestMatch = data.productId;
    bestConfidence = confidence;
  }

  await new Promise((resolve) => setTimeout(resolve, 0));
}

if (bestMatch && bestConfidence >= 90) {
  return bestMatch;
}

  return null;
}

async function suggestFromPhoto(dataUrl) {
  const response = await fetch("/api/vision", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ action: "suggest", dataUrl })
  });
  if (!response.ok) throw new Error("No se pudo analizar la foto");
  const data = await response.json();
  return { nombre: data.nombre || "" };
}

function mapProduct(row) {
  return {
    id: row.id,
    nombre: row.nombre || "",
    precio: Number(row.precio) || 0,
    costo: Number(row.costo) || 0,
    stock: Number(row.stock) || 0,
    proveedor: row.proveedor || "",
    foto: row.foto || null,
    creadoEn: row.created_at || null
  };
}

function mapSale(row) {
  return {
    id: row.id,
    productId: row.product_id,
    nombre: row.nombre || "",
    cantidad: Number(row.cantidad) || 0,
    precioUnitario: Number(row.precio_unitario) || 0,
    costoUnitario: Number(row.costo_unitario) || 0,
    total: Number(row.total) || 0,
    userId: row.user_id || null,
    fecha: row.fecha
  };
}

function mapAdjustment(row) {
  return {
    id: row.id,
    tipo: row.tipo,
    productoOriginalId: row.producto_original_id,
    productoOriginalNombre: row.producto_original_nombre || "",
    cantidadOriginal: Number(row.cantidad_original) || 0,
    productoReemplazoId: row.producto_reemplazo_id || null,
    productoReemplazoNombre: row.producto_reemplazo_nombre || null,
    cantidadReemplazo: row.cantidad_reemplazo == null ? null : Number(row.cantidad_reemplazo),
    comentario: row.comentario || "",
    userId: row.user_id || null,
    fecha: row.fecha
  };
}

async function uploadProductPhoto(productId, foto, userId) {
  if (!foto || !foto.startsWith("data:")) return foto || null;
  const blob = await (await fetch(foto)).blob();
  const ext = blob.type === "image/png" ? "png" : blob.type === "image/webp" ? "webp" : "jpg";
  const path = `${userId}/${productId}.${ext}`;
  const { error } = await supabase.storage.from("product-photos").upload(path, blob, {
    upsert: true,
    contentType: blob.type || "image/jpeg"
  });
  if (error) throw error;
  const { data } = supabase.storage.from("product-photos").getPublicUrl(path);
  return data.publicUrl;
}

function LoginScreen() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [nombre, setNombre] = useState("");
  const [mode, setMode] = useState("login");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const submit = async (e) => {
    e.preventDefault();
    setLoading(true); setMessage("");
    try {
      if (mode === "signup") {
        const { error } = await supabase.auth.signUp({
          email: email.trim(), password,
          options: { data: { nombre: nombre.trim() } }
        });
        if (error) throw error;
        setMessage("Cuenta creada. Si Supabase solicita confirmación, revisá tu correo y luego iniciá sesión.");
        setMode("login");
      } else {
        const { error } = await supabase.auth.signInWithPassword({ email: email.trim(), password });
        if (error) throw error;
      }
    } catch (e) {
      setMessage(e?.message || "No se pudo iniciar sesión.");
    } finally { setLoading(false); }
  };

  return (
    <div style={{ minHeight: "100vh", background: "#F7F0E5", display: "grid", placeItems: "center", padding: 20, fontFamily: "'Public Sans', sans-serif" }}>
      <style>{`${FONT_IMPORT} *{box-sizing:border-box}`}</style>
      <form onSubmit={submit} style={{ width: "100%", maxWidth: 390, background: "#FFFDF9", border: "1px solid #E1D1BC", borderRadius: 10, padding: 24, boxShadow: "0 12px 35px rgba(80,50,25,.08)" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 22 }}>
          <img src={LOGO_DATA_URL} alt="Pinti Mates" style={{ width: 44, height: 44, objectFit: "contain" }} />
          <div><div style={{ fontWeight: 800, fontSize: 20 }}>Pinti Mates</div><div style={{ color: "#8A6F52", fontSize: 13 }}>Inventario compartido</div></div>
        </div>
        {mode === "signup" && <Field label="Nombre"><input style={styles.input} value={nombre} onChange={e=>setNombre(e.target.value)} required /></Field>}
        <Field label="Correo electrónico"><input type="email" style={styles.input} value={email} onChange={e=>setEmail(e.target.value)} required /></Field>
        <Field label="Contraseña"><input type="password" minLength={6} style={styles.input} value={password} onChange={e=>setPassword(e.target.value)} required /></Field>
        {message && <div style={{ marginBottom: 12, fontSize: 13, color: "#8B5A35", background: "#F6E7D3", padding: 10, borderRadius: 5 }}>{message}</div>}
        <button disabled={loading} style={{ ...styles.primaryButton, width: "100%", justifyContent: "center" }}>{loading ? "Procesando…" : mode === "login" ? "Ingresar" : "Crear cuenta"}</button>
        <button type="button" onClick={()=>{setMode(mode === "login" ? "signup" : "login"); setMessage("");}} style={{ ...styles.ghostButton, width: "100%", justifyContent: "center", marginTop: 10 }}>
          {mode === "login" ? "Crear un usuario nuevo" : "Ya tengo cuenta"}
        </button>
      </form>
    </div>
  );
}

export default function App() {
  const [session, setSession] = useState(null);
  const [checking, setChecking] = useState(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => { setSession(data.session || null); setChecking(false); });
    const { data: listener } = supabase.auth.onAuthStateChange((_event, next) => { setSession(next); setChecking(false); });
    return () => listener.subscription.unsubscribe();
  }, []);

  if (checking) return <div style={{ padding: 30, fontFamily: "sans-serif" }}>Cargando Pinti Mates…</div>;
  if (!session) return <LoginScreen />;
  return <BusinessApp session={session} />;
}

function BusinessApp({ session }) {
  const [products, setProducts] = useState([]);
  const [sales, setSales] = useState([]);
  const [ajustes, setAjustes] = useState([]);
  const [ready, setReady] = useState(false);
  const [view, setView] = useState(() => localStorage.getItem("pinti-view") || "resumen");

useEffect(() => {
  localStorage.setItem("pinti-view", view);
}, [view]);
  const [editingId, setEditingId] = useState(null);
  const [lowStockThreshold, setLowStockThreshold] = useState(LOW_STOCK_DEFAULT);

  const loadAll = async () => {
    const [pRes, sRes, aRes] = await Promise.all([
      supabase.from("products").select("*").order("nombre"),
      supabase.from("sales").select("*").order("fecha", { ascending: false }),
      supabase.from("adjustments").select("*").order("fecha", { ascending: false })
    ]);
    const error = pRes.error || sRes.error || aRes.error;
    if (error) throw error;
    setProducts((pRes.data || []).map(mapProduct));
    setSales((sRes.data || []).map(mapSale));
    setAjustes((aRes.data || []).map(mapAdjustment));
  };

  useEffect(() => {
    let active = true;
    (async () => {
      try { await loadAll(); } catch (e) { console.error(e); }
      finally { if (active) setReady(true); }
    })();
    const channel = supabase.channel("pinti-mates-live")
      .on("postgres_changes", { event: "*", schema: "public", table: "products" }, () => loadAll())
      .on("postgres_changes", { event: "*", schema: "public", table: "sales" }, () => loadAll())
      .on("postgres_changes", { event: "*", schema: "public", table: "adjustments" }, () => loadAll())
      .subscribe();
    return () => { active = false; supabase.removeChannel(channel); };
  }, []);

  const totalStockValue = useMemo(
    () => products.reduce((sum, p) => sum + (Number(p.precio) || 0) * (Number(p.stock) || 0), 0),
    [products]
  );
  const lowStock = useMemo(
    () => products.filter((p) => Number(p.stock) <= lowStockThreshold),
    [products, lowStockThreshold]
  );
  const todayStr = new Date().toDateString();
  const salesToday = useMemo(
    () => sales.filter((s) => new Date(s.fecha).toDateString() === todayStr),
    [sales]
  );
  const todayTotal = salesToday.reduce((sum, s) => sum + s.total, 0);

  const saveProduct = async (product) => {
    try {
      const photoUrl = await uploadProductPhoto(product.id, product.foto, session.user.id);
      const payload = {
        id: product.id,
        nombre: product.nombre,
        precio: Number(product.precio) || 0,
        costo: Number(product.costo) || 0,
        stock: Math.max(0, Number(product.stock) || 0),
        proveedor: product.proveedor || "",
modelo: product.modelo || "",
material: product.material || "",
color: product.color || "",
terminacion: product.terminacion || "",
virola: product.virola || "",
guarda: product.guarda || "",
base: product.base || "",
patas: product.patas || "",
bolitas: product.bolitas || "",
detalles: product.detalles || "",
foto: photoUrl
      };
      const { error } = await supabase.from("products").upsert(payload);
      if (error) throw error;
      await loadAll();
    } catch (e) {
      alert(`No se pudo guardar el producto: ${e?.message || e}`);
      throw e;
    }
  };

  const deleteProduct = async (id) => {
    const { error } = await supabase.from("products").delete().eq("id", id);
    if (error) { alert(`No se pudo eliminar: ${error.message}`); return; }
    await loadAll();
  };

  const registerSale = async (productId, qty) => {
    const { error } = await supabase.rpc("register_sale", { p_product_id: productId, p_qty: Number(qty) });
    if (error) { alert(`No se pudo registrar la venta: ${error.message}`); return false; }
    await loadAll();
    return true;
  };

  const registrarAjuste = async ({ tipo, productoOriginalId, cantidadOriginal, productoReemplazoId, cantidadReemplazo, comentario }) => {
    const { error } = await supabase.rpc("register_adjustment", {
      p_tipo: tipo,
      p_original_id: productoOriginalId,
      p_cantidad_original: Number(cantidadOriginal),
      p_reemplazo_id: tipo === "cambio" ? productoReemplazoId : null,
      p_cantidad_reemplazo: tipo === "cambio" ? Number(cantidadReemplazo) : null,
      p_comentario: comentario || ""
    });
    if (error) { alert(`No se pudo registrar el ajuste: ${error.message}`); return false; }
    await loadAll();
    return true;
  };

  const navItems = [
    { id: "resumen", label: "Resumen", icon: Home },
    { id: "inventario", label: "Inventario", icon: Package },
    { id: "venta", label: "Nueva venta", icon: ShoppingCart },
    { id: "ventaFoto", label: "Venta por foto", icon: Camera },
    { id: "cambios", label: "Cambios y bajas", icon: RefreshCcw },
    { id: "precios", label: "Lista de precios", icon: List },
    { id: "estadisticas", label: "Estadísticas", icon: BarChart3 }
  ];

  return (
    <div style={styles.appShell}>
      <style>{`
        ${FONT_IMPORT}
        * { box-sizing: border-box; }
        .naveg-item:hover { background: #F3E7D3; }
        .naveg-item.active { background-image: linear-gradient(135deg, #C08C5D, #8B5A35); color: #FFFFFF; box-shadow: 0 2px 8px rgba(139,90,53,0.28); }
        .fila-tabla:hover { background: #FAF3E8; }
        input:focus, select:focus, textarea:focus, button:focus-visible {
          outline: 2px solid #A8754E; outline-offset: 1px;
        }
        button { cursor: pointer; transition: transform .12s ease, filter .12s ease, box-shadow .12s ease; }
        button:not(:disabled):hover { filter: brightness(1.05); }
        button:not(:disabled):active { transform: scale(0.97); }
        button:disabled { opacity: 0.5; cursor: not-allowed; }
        @media print {
          .no-imprimir { display: none !important; }
          .imprimir-full { display: block !important; padding: 0 !important; }
        }
        @media (max-width: 760px) {
          .barra-lateral { display: none !important; }
          .barra-inferior { display: flex !important; }
          .barra-superior-movil { display: flex !important; }
          .contenido-principal { padding-bottom: calc(92px + env(safe-area-inset-bottom)) !important; padding-top: calc(16px + env(safe-area-inset-top)) !important; padding-left: 14px !important; padding-right: 14px !important; }
          .tabla-movil { overflow-x: auto; -webkit-overflow-scrolling: touch; }
        }
      `}</style>

      <nav className="barra-lateral" style={styles.sidebar}>
        <div style={styles.brand}>
          <img src={LOGO_DATA_URL} alt="Pinti Mates" style={styles.brandLogo} />
          <div>
            <div style={{ fontWeight: 700, fontSize: 15 }}>Pinti Mates</div>
            <div style={{ fontSize: 12, color: "#8A6F52" }}>Control de inventario</div>
          </div>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 4, marginTop: 8 }}>
          {navItems.map((item) => (
            <button
              key={item.id}
              className={`naveg-item${view === item.id ? " active" : ""}`}
              onClick={() => { setView(item.id); setEditingId(null); }}
              style={styles.navButton}
            >
              <item.icon size={18} />
              <span>{item.label}</span>
            </button>
          ))}
        </div>
        <button
          style={{ ...styles.navButton, marginTop: "auto", border: "1px solid #A8754E", color: "#A8754E" }}
          onClick={() => { setEditingId("new"); setView("nuevo"); }}
        >
          <Plus size={18} />
          <span>Nuevo producto</span>
        </button>
        <button
          style={{ ...styles.navButton, marginTop: 6, color: "#8A6F52" }}
          onClick={() => supabase.auth.signOut()}
        >
          <span>Cerrar sesión</span>
        </button>
      </nav>

      <main className="contenido-principal" style={styles.main}>
        <div className="barra-superior-movil no-imprimir" style={styles.mobileTopBar}>
          <img src={LOGO_DATA_URL} alt="Pinti Mates" style={styles.mobileTopLogo} />
          <span style={{ fontWeight: 700, fontSize: 15 }}>Pinti Mates</span>
          <button onClick={() => supabase.auth.signOut()} style={{ marginLeft: "auto", border: 0, background: "transparent", color: "#8A6F52", fontSize: 12 }}>Salir</button>
        </div>
        {!ready ? (
          <div style={styles.loadingState}>
            <Loader2 size={22} className="spin" style={{ animation: "spin 1s linear infinite" }} />
            <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
            Cargando datos del negocio…
          </div>
        ) : view === "resumen" ? (
          <Resumen
            totalStockValue={totalStockValue}
            productCount={products.length}
            lowStock={lowStock}
            lowStockThreshold={lowStockThreshold}
            setLowStockThreshold={setLowStockThreshold}
            salesTodayCount={salesToday.length}
            todayTotal={todayTotal}
            onGoInventario={() => setView("inventario")}
          />
        ) : view === "inventario" ? (
          <Inventario
            products={products}
            lowStockThreshold={lowStockThreshold}
            onEdit={(id) => { setEditingId(id); setView("nuevo"); }}
            onDelete={deleteProduct}
            onNuevo={() => { setEditingId("new"); setView("nuevo"); }}
          />
        ) : view === "nuevo" ? (
          <FormularioProducto
            products={products}
            product={editingId && editingId !== "new" ? products.find((p) => p.id === editingId) : null}
            onSave={async (p) => { await saveProduct(p); setView("inventario"); }}
            onCancel={() => setView("inventario")}
          />
        ) : view === "venta" ? (
          <NuevaVenta products={products} sales={sales} onRegister={registerSale} />
        ) : view === "ventaFoto" ? (
          <VentaPorFoto products={products} onRegister={registerSale} />
     ) : view === "mas" ? (
  <div>
    <PageHeader
      title="Más opciones"
      subtitle="Administración y herramientas"
    />

    <div style={{ display: "grid", gap: 12 }}>
      <button
        style={styles.secondaryButton}
        onClick={() => {
          setEditingId("new");
          setView("nuevo");
        }}
      >
        <Plus size={18} />
        Nuevo producto
      </button>

      <button
        style={styles.secondaryButton}
        onClick={() => setView("cambios")}
      >
        <RefreshCcw size={18} />
        Cambios y bajas
      </button>

      <button
        style={styles.secondaryButton}
        onClick={() => setView("precios")}
      >
        <List size={18} />
        Lista de precios
      </button>

      <button
        style={styles.secondaryButton}
        onClick={() => setView("estadisticas")}
      >
        <BarChart3 size={18} />
        Estadísticas
      </button>

      <button
        style={{
          ...styles.secondaryButton,
          color: "#B23A34",
          borderColor: "#B23A34"
        }}
        onClick={() => supabase.auth.signOut()}
      >
        Cerrar sesión
      </button>
    </div>
  </div>   
    ) : view === "cambios" ? (
          <CambiosBajas products={products} ajustes={ajustes} onRegistrarAjuste={registrarAjuste} />
        ) : view === "precios" ? (
          <ListaPrecios products={products} />
        ) : (
          <Estadisticas products={products} sales={sales} ajustes={ajustes} />
        )}
      </main>

      <nav className="barra-inferior no-imprimir" style={styles.bottomBar}>
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => { setView(item.id); setEditingId(null); }}
            style={{
              ...styles.bottomBarButton,
              color: view === item.id ? "#A8754E" : "#8A6F52"
            }}
          >
            <item.icon size={19} />
            <span style={{ fontSize: 10.5 }}>{item.label}</span>
          </button>
        ))}
        <button
          onClick={() => { setEditingId("new"); setView("nuevo"); }}
          style={{ ...styles.bottomBarButton, color: view === "nuevo" ? "#A8754E" : "#8A6F52" }}
        >
          <Plus size={19} />
          <span style={{ fontSize: 10.5 }}>Nuevo</span>
        </button>
      </nav>
    </div>
  );
}

function Resumen({ totalStockValue, productCount, lowStock, lowStockThreshold, setLowStockThreshold, salesTodayCount, todayTotal, onGoInventario }) {
  return (
    <div>
      <PageHeader title="Resumen" subtitle="Así está tu negocio hoy" />
      <div style={styles.statGrid}>
        <StatBlock label="Productos en inventario" value={productCount} />
        <StatBlock label="Valor total del stock" value={`$${money(totalStockValue)}`} mono />
        <StatBlock label="Ventas de hoy" value={salesTodayCount} />
        <StatBlock label="Total vendido hoy" value={`$${money(todayTotal)}`} mono />
      </div>

      <div style={{ ...styles.panel, marginTop: 20 }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <AlertTriangle size={18} color="#CE9B3F" />
            <span style={{ fontWeight: 700 }}>Stock bajo</span>
          </div>
          <label style={{ fontSize: 13, color: "#8A6F52", display: "flex", alignItems: "center", gap: 6 }}>
            Umbral:
            <input
              type="number"
              min={0}
              value={lowStockThreshold}
              onChange={(e) => setLowStockThreshold(Math.max(0, Number(e.target.value) || 0))}
              style={{ ...styles.inputSmall, width: 60 }}
            />
          </label>
        </div>
        {lowStock.length === 0 ? (
          <div style={{ color: "#8A6F52", fontSize: 14 }}>No hay productos con stock bajo. Todo en orden.</div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {lowStock.map((p) => (
              <div key={p.id} style={styles.lowStockRow}>
                <span>{p.nombre}</span>
                <span style={{ fontFamily: "'JetBrains Mono', monospace", color: p.stock <= 0 ? "#B23A34" : "#CE9B3F" }}>
                  {p.stock} en stock
                </span>
              </div>
            ))}
          </div>
        )}
        <button onClick={onGoInventario} style={{ ...styles.linkButton, marginTop: 12 }}>
          Ver inventario completo →
        </button>
      </div>
    </div>
  );
}

