function NuevaVenta({ products, sales, onRegister }) {
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState(null);
  const [qty, setQty] = useState(1);
  const [message, setMessage] = useState(null);

  const selected = products.find((p) => p.id === selectedId);
  const filtered = products.filter((p) => p.nombre.toLowerCase().includes(query.toLowerCase()));
  const recent = sales.slice(0, 8);

  const submit = () => {
    if (!selected) return;
    if (qty <= 0) return;
    if (qty > selected.stock) {
      setMessage({ type: "error", text: `Solo hay ${selected.stock} unidades disponibles.` });
      return;
    }
    onRegister(selected.id, qty);
    setMessage({ type: "success", text: `Venta registrada: ${qty} × ${selected.nombre}.` });
    setSelectedId(null);
    setQuery("");
    setQty(1);
  };

  return (
    <div>
      <PageHeader title="Nueva venta" subtitle="Elegí el producto y la cantidad vendida" />

      <div style={styles.panel}>
        {!selected ? (
          <>
            <div style={{ position: "relative", marginBottom: 12 }}>
              <Search size={16} style={{ position: "absolute", left: 12, top: 11, color: "#A68A68" }} />
              <input
                placeholder="Buscar producto"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                style={{ ...styles.input, paddingLeft: 36 }}
              />
            </div>
            {products.length === 0 ? (
              <EmptyState title="No hay productos cargados" detail="Cargá productos en el inventario antes de registrar ventas." />
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 320, overflowY: "auto" }}>
                {filtered.map((p) => (
                  <button
                    key={p.id}
                    onClick={() => { setSelectedId(p.id); setMessage(null); }}
                    style={styles.selectRow}
                    disabled={p.stock <= 0}
                  >
                    <span>{p.nombre}</span>
                    <span style={{ display: "flex", gap: 14, alignItems: "center" }}>
                      <span style={{ fontFamily: "'JetBrains Mono', monospace", color: "#8A6F52" }}>${money(p.precio)}</span>
                      <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 12, color: p.stock <= 0 ? "#B23A34" : "#8A6F52" }}>
                        {p.stock <= 0 ? "sin stock" : `${p.stock} en stock`}
                      </span>
                    </span>
                  </button>
                ))}
              </div>
            )}
          </>
        ) : (
          <div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div>
                <div style={{ fontWeight: 700, fontSize: 17 }}>{selected.nombre}</div>
                <div style={{ color: "#8A6F52", fontSize: 13, marginTop: 2 }}>
                  ${money(selected.precio)} · {selected.stock} disponibles
                </div>
              </div>
              <button style={styles.iconButton} onClick={() => setSelectedId(null)} aria-label="Cambiar producto">
                <X size={16} />
              </button>
            </div>

            <div style={{ display: "flex", alignItems: "center", gap: 14, marginTop: 20 }}>
              <span style={{ fontSize: 13, color: "#8A6F52" }}>Cantidad</span>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <button style={styles.stepperButton} onClick={() => setQty((q) => Math.max(1, q - 1))}><Minus size={14} /></button>
                <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 18, minWidth: 28, textAlign: "center" }}>{qty}</span>
                <button style={styles.stepperButton} onClick={() => setQty((q) => Math.min(selected.stock, q + 1))}><Plus size={14} /></button>
              </div>
            </div>

            <div style={{ marginTop: 18, fontSize: 15 }}>
              Total: <span style={{ fontFamily: "'JetBrains Mono', monospace", fontWeight: 700 }}>${money(selected.precio * qty)}</span>
            </div>

            <button style={{ ...styles.primaryButton, marginTop: 18 }} onClick={submit}>
              <Check size={16} /> Registrar venta
            </button>
          </div>
        )}

        {message && (
          <div style={{
            marginTop: 16, padding: "10px 12px", borderRadius: 4, fontSize: 13,
            background: message.type === "error" ? "#FBEAE9" : "#F6E7D3",
            color: message.type === "error" ? "#B23A34" : "#A8754E"
          }}>
            {message.text}
          </div>
        )}
      </div>

      {recent.length > 0 && (
        <div style={{ marginTop: 20 }}>
          <div style={{ fontWeight: 700, marginBottom: 10, fontSize: 14 }}>Últimas ventas</div>
          <div style={styles.tableWrap}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Producto</th>
                  <th style={{ ...styles.th, textAlign: "right" }}>Cant.</th>
                  <th style={{ ...styles.th, textAlign: "right" }}>Total</th>
                  <th style={styles.th}>Fecha</th>
                </tr>
              </thead>
              <tbody>
                {recent.map((s) => (
                  <tr key={s.id} className="fila-tabla">
                    <td style={styles.td}>{s.nombre}</td>
                    <td style={{ ...styles.td, textAlign: "right", fontFamily: "'JetBrains Mono', monospace" }}>{s.cantidad}</td>
                    <td style={{ ...styles.td, textAlign: "right", fontFamily: "'JetBrains Mono', monospace" }}>${money(s.total)}</td>
                    <td style={{ ...styles.td, color: "#8A6F52", fontSize: 12.5 }}>
                      {new Date(s.fecha).toLocaleString("es-AR")}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

function VentaPorFoto({ products, onRegister }) {
  const [foto, setFoto] = useState(null);
  const [buscando, setBuscando] = useState(false);
  const [match, setMatch] = useState(null);
  const [sinMatch, setSinMatch] = useState(false);
  const [qty, setQty] = useState(1);
  const [mensaje, setMensaje] = useState(null);
  const [ventaConfirmada, setVentaConfirmada] = useState(null);
  const [busquedaManual, setBusquedaManual] = useState("");
  const fileInputRef = useRef(null);
const [camaraActiva, setCamaraActiva] = useState(false);
const videoRef = useRef(null);
const streamRef = useRef(null);
  const abrirCamara = async () => {
  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      video: {
        facingMode: { ideal: "environment" },
        width: { ideal: 1280 },
        height: { ideal: 720 }
      },
      audio: false
    });

    streamRef.current = stream;
    setCamaraActiva(true);

   requestAnimationFrame(() => {
  requestAnimationFrame(async () => {
    if (videoRef.current) {
      videoRef.current.srcObject = stream;
      try {
        await videoRef.current.play();
      } catch (error) {
        console.error("No se pudo iniciar la vista de cámara:", error);
      }
    }
  });
}); 
  } catch (error) {
    console.error(error);
    setMensaje("No se pudo abrir la cámara. Revisá el permiso de cámara.");
  }
};

const cerrarCamara = () => {
  if (streamRef.current) {
    streamRef.current.getTracks().forEach((track) => track.stop());
    streamRef.current = null;
  }
  setCamaraActiva(false);
};
  const capturarFoto = async () => {
  const video = videoRef.current;
  if (!video || !video.videoWidth || !video.videoHeight) return;

  const maxWidth = 960;
  const scale = Math.min(1, maxWidth / video.videoWidth);

  const canvas = document.createElement("canvas");
  canvas.width = Math.round(video.videoWidth * scale);
  canvas.height = Math.round(video.videoHeight * scale);

  const ctx = canvas.getContext("2d");
  ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

  canvas.toBlob(async (blob) => {
    if (!blob) return;

    const file = new File([blob], "foto-mate.jpg", {
      type: "image/jpeg"
    });

    cerrarCamara();
    await handlePhoto(file);
  }, "image/jpeg", 0.72);
};
  const conFoto = products.filter((p) => p.foto);

  const reset = () => {
    setFoto(null); setMatch(null); setSinMatch(false); setQty(1);
    setMensaje(null); setVentaConfirmada(null); setBusquedaManual("");
  };

  const handleFoto = async (file) => {
    if (!file) return;
    reset();
    try {
      const dataUrl = await resizeImage(file, 320, 0.50 );
      setFoto(dataUrl);
      await new Promise((resolve) => setTimeout(resolve, 300));
            
      if (conFoto.length === 0) {
        setSinMatch(true);
       
      }
      setBuscando(true);
      try {
        const candidates = conFoto.slice(0, 30);
        const productId = await matchProductByPhoto(dataUrl, candidates);
        const found = productId ? products.find((p) => p.id === productId) : null;
        if (found) {
          setMatch(found);
          setQty(1);
        } else {
          setSinMatch(true);
        }
      } catch (e) {
        setMensaje({ type: "error", text: "No se pudo identificar el producto automáticamente. Buscalo manualmente abajo." });
        setSinMatch(true);
      } finally {
        setBuscando(false);
      }
    } catch (e) {
      setMensaje({ type: "error", text: e?.message || "No se pudo procesar la foto." });
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const confirmar = () => {
    if (!match) return;
    if (qty <= 0) return;
    if (qty > match.stock) {
      setMensaje({ type: "error", text: `Solo hay ${match.stock} unidades disponibles.` });
      return;
    }
    onRegister(match.id, qty);
    setVentaConfirmada({ nombre: match.nombre, cantidad: qty, total: match.precio * qty });
  };

  const filtradosManual = products.filter((p) => p.nombre.toLowerCase().includes(busquedaManual.toLowerCase()));

  return (
    <div style={{ maxWidth: 480 }}>
      <PageHeader title="Venta por foto" subtitle="Sacale una foto al producto y lo buscamos en el inventario" />

      {conFoto.length === 0 && !foto && (
        <div style={{
          marginBottom: 16, padding: "10px 12px", borderRadius: 4, fontSize: 13,
          background: "#FDF3E7", color: "#CE9B3F"
        }}>
          Todavía no hay productos con foto cargada en el inventario. Este método funciona mejor cuando los productos tienen foto.
        </div>
      )}

      <div style={styles.panel}>
        {ventaConfirmada ? (
          <div style={{ textAlign: "center", padding: "12px 0" }}>
            <div style={{ display: "flex", justifyContent: "center", marginBottom: 12 }}>
              <div style={{
                width: 48, height: 48, borderRadius: "50%", background: "#F6E7D3",
                display: "flex", alignItems: "center", justifyContent: "center"
              }}>
                <Check size={24} color="#A8754E" />
              </div>
            </div>
            <div style={{ fontSize: 14, color: "#8A6F52" }}>{ventaConfirmada.cantidad} × {ventaConfirmada.nombre}</div>
            <div style={{ fontSize: 30, fontWeight: 800, fontFamily: "'JetBrains Mono', monospace", marginTop: 6 }}>
              ${money(ventaConfirmada.total)}
            </div>
            <button style={{ ...styles.primaryButton, marginTop: 18 }} onClick={reset}>
              <Camera size={16} /> Escanear otro producto
            </button>
          </div>
        ) : !foto ? (
          <div style={{ textAlign: "center", padding: "20px 0" }}>
            <input
  ref={fileInputRef}
  type="file"
  accept="image/*"
  capture="environment"
  style={{ display: "none" }}
  onChange={(e) => handlePhoto(e.target.files?.[0])}
/>

<button
  type="button"
  style={styles.primaryButton}
  onClick={() => fileInputRef.current?.click()}
>
  <Camera size={16} /> Sacar foto del producto
</button>
            <div style={{ fontSize: 13, color: "#8A6F52", marginTop: 12 }}>
              Buscamos el producto comparando la foto con las que ya cargaste en el inventario.
            </div>
          </div>
        ) : (
          <div>
            <div style={{ display: "flex", gap: 14, alignItems: "flex-start" }}>
              <img src={match?.foto || foto} alt="Producto" style={{ width: 72, height: 72, borderRadius: 4, objectFit: "cover", flexShrink: 0 }} />
              <div style={{ flex: 1 }}>
                {buscando ? (
                  <div style={{ display: "flex", alignItems: "center", gap: 8, color: "#8A6F52", fontSize: 14 }}>
                    <Loader2 size={16} style={{ animation: "spin 1s linear infinite" }} />
                    Buscando en el inventario…
                  </div>
                ) : match ? (
                  <div>
                    <div style={{ fontWeight: 700, fontSize: 16 }}>{match.nombre}</div>
                    <div style={{ color: "#8A6F52", fontSize: 13, marginTop: 2 }}>
                      ${money(match.precio)} · {match.stock} disponibles
                    </div>
                  </div>
                ) : (
                  <div style={{ fontSize: 14, color: "#B23A34" }}>No se encontró un producto que coincida con esta foto.</div>
                )}
              </div>
              <button style={styles.iconButton} onClick={reset} aria-label="Cancelar"><X size={16} /></button>
            </div>

            {!buscando && match && (
              <>
                <div style={{ display: "flex", alignItems: "center", gap: 14, marginTop: 20 }}>
                  <span style={{ fontSize: 13, color: "#8A6F52" }}>Cantidad</span>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <button style={styles.stepperButton} onClick={() => setQty((q) => Math.max(1, q - 1))}><Minus size={14} /></button>
                    <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 18, minWidth: 28, textAlign: "center" }}>{qty}</span>
                    <button style={styles.stepperButton} onClick={() => setQty((q) => Math.min(match.stock, q + 1))}><Plus size={14} /></button>
                  </div>
                </div>
                <div style={{ marginTop: 16, fontSize: 15 }}>
                  Total: <span style={{ fontFamily: "'JetBrains Mono', monospace", fontWeight: 700 }}>${money(match.precio * qty)}</span>
                </div>
                <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
                  <button style={styles.primaryButton} onClick={confirmar}>
                    <Check size={16} /> Confirmar venta
                  </button>
                  <button style={styles.ghostButton} onClick={() => { setMatch(null); setSinMatch(true); }}>
                    No es este producto
                  </button>
                </div>
              </>
            )}

            {!buscando && sinMatch && (
              <div style={{ marginTop: 20 }}>
                <div style={{ fontSize: 13, color: "#8A6F52", marginBottom: 8 }}>Buscá el producto manualmente:</div>
                <div style={{ position: "relative", marginBottom: 10 }}>
                  <Search size={16} style={{ position: "absolute", left: 12, top: 11, color: "#A68A68" }} />
                  <input
                    placeholder="Nombre del producto"
                    value={busquedaManual}
                    onChange={(e) => setBusquedaManual(e.target.value)}
                    style={{ ...styles.input, paddingLeft: 36 }}
                  />
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 220, overflowY: "auto" }}>
                  {filtradosManual.map((p) => (
                    <button
                      key={p.id}
                      onClick={() => { setMatch(p); setSinMatch(false); setQty(1); }}
                      style={styles.selectRow}
                      disabled={p.stock <= 0}
                    >
                      <span>{p.nombre}</span>
                      <span style={{ display: "flex", gap: 14, alignItems: "center" }}>
                        <span style={{ fontFamily: "'JetBrains Mono', monospace", color: "#8A6F52" }}>${money(p.precio)}</span>
                        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 12, color: p.stock <= 0 ? "#B23A34" : "#8A6F52" }}>
                          {p.stock <= 0 ? "sin stock" : `${p.stock} en stock`}
                        </span>
                      </span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {mensaje && (
          <div style={{
            marginTop: 16, padding: "10px 12px", borderRadius: 4, fontSize: 13,
            background: mensaje.type === "error" ? "#FBEAE9" : "#F6E7D3",
            color: mensaje.type === "error" ? "#B23A34" : "#A8754E"
          }}>
            {mensaje.text}
          </div>
        )}
      </div>
    </div>
  );
}

function BuscadorProducto({ products, query, setQuery, onSelect, placeholder }) {
  const filtrados = products.filter((p) => p.nombre.toLowerCase().includes(query.toLowerCase()));
  return (
    <div>
      <div style={{ position: "relative", marginBottom: 8 }}>
        <Search size={15} style={{ position: "absolute", left: 11, top: 10, color: "#A68A68" }} />
        <input
          placeholder={placeholder}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          style={{ ...styles.input, paddingLeft: 32, fontSize: 13.5 }}
        />
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 5, maxHeight: 180, overflowY: "auto" }}>
        {filtrados.length === 0 ? (
          <div style={{ fontSize: 13, color: "#8A6F52", padding: "6px 2px" }}>Sin resultados.</div>
        ) : (
          filtrados.map((p) => (
            <button key={p.id} onClick={() => onSelect(p)} style={{ ...styles.selectRow, padding: "8px 10px", fontSize: 13.5 }}>
              <span>{p.nombre}</span>
              <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 12, color: "#8A6F52" }}>{p.stock} en stock</span>
            </button>
          ))
        )}
      </div>
    </div>
  );
}

function CambiosBajas({ products, ajustes, onRegistrarAjuste }) {
  const [tipo, setTipo] = useState("cambio");
  const [original, setOriginal] = useState(null);
  const [cantidadOriginal, setCantidadOriginal] = useState(1);
  const [queryOriginal, setQueryOriginal] = useState("");
  const [reemplazo, setReemplazo] = useState(null);
  const [cantidadReemplazo, setCantidadReemplazo] = useState(1);
  const [queryReemplazo, setQueryReemplazo] = useState("");
  const [comentario, setComentario] = useState("");
  const [mensaje, setMensaje] = useState(null);

  const reset = () => {
    setOriginal(null); setCantidadOriginal(1); setQueryOriginal("");
    setReemplazo(null); setCantidadReemplazo(1); setQueryReemplazo("");
    setComentario("");
  };

  const puedeConfirmar =
    original &&
    cantidadOriginal > 0 &&
    cantidadOriginal <= original.stock &&
    comentario.trim().length > 0 &&
    (tipo === "baja" || (reemplazo && cantidadReemplazo > 0 && cantidadReemplazo <= reemplazo.stock));

  const confirmar = async () => {
    if (!puedeConfirmar) return;
    await onRegistrarAjuste({
      tipo,
      productoOriginalId: original.id,
      cantidadOriginal,
      productoReemplazoId: tipo === "cambio" ? reemplazo.id : null,
      cantidadReemplazo: tipo === "cambio" ? cantidadReemplazo : null,
      comentario
    });
    setMensaje({
      type: "success",
      text: tipo === "cambio"
        ? `Cambio registrado: ${cantidadOriginal} × ${original.nombre} por ${cantidadReemplazo} × ${reemplazo.nombre}.`
        : `Baja registrada: ${cantidadOriginal} × ${original.nombre} por falla.`
    });
    reset();
  };

  const historial = ajustes.slice(0, 10);

  return (
    <div style={{ maxWidth: 620 }}>
      <PageHeader title="Cambios y bajas" subtitle="Registrá roturas, fallas o cambios y se descuentan del stock automáticamente" />

      <div style={styles.panel}>
        <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
          <button
            onClick={() => { setTipo("cambio"); reset(); }}
            style={{
              ...styles.secondaryButton,
              flex: 1, justifyContent: "center",
              background: tipo === "cambio" ? "#A8754E" : "#FFFFFF",
              color: tipo === "cambio" ? "#FFFFFF" : "#8B5A35"
            }}
          >
            <RefreshCcw size={15} /> Cambio por falla
          </button>
          <button
            onClick={() => { setTipo("baja"); reset(); }}
            style={{
              ...styles.secondaryButton,
              flex: 1, justifyContent: "center",
              background: tipo === "baja" ? "#A8754E" : "#FFFFFF",
              color: tipo === "baja" ? "#FFFFFF" : "#8B5A35"
            }}
          >
            <Trash2 size={15} /> Baja por falla
          </button>
        </div>

        <div style={{ fontSize: 13, color: "#8A6F52", marginBottom: 16, lineHeight: 1.5 }}>
          {tipo === "cambio"
            ? "El producto roto o fallado se descuenta del stock y se entrega otro producto en su lugar, que también se descuenta."
            : "El producto se descarta por falla antes de venderse. Se descuenta del stock sin entregar ningún reemplazo."}
        </div>

        <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 8 }}>
          {tipo === "cambio" ? "Producto roto / fallado" : "Producto a dar de baja"}
        </div>

        {original ? (
          <div style={{ ...styles.selectRow, marginBottom: 14 }}>
            <span>{original.nombre}</span>
            <button style={{ ...styles.iconButton, marginLeft: 12 }} onClick={() => setOriginal(null)} aria-label="Cambiar selección">
              <X size={14} />
            </button>
          </div>
        ) : (
          <div style={{ marginBottom: 14 }}>
            <BuscadorProducto
              products={products}
              query={queryOriginal}
              setQuery={setQueryOriginal}
              onSelect={(p) => { setOriginal(p); setCantidadOriginal(1); }}
              placeholder="Buscar producto"
            />
          </div>
        )}

        {original && (
          <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 18 }}>
            <span style={{ fontSize: 13, color: "#8A6F52" }}>Cantidad</span>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <button style={styles.stepperButton} onClick={() => setCantidadOriginal((q) => Math.max(1, q - 1))}><Minus size={14} /></button>
              <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 16, minWidth: 24, textAlign: "center" }}>{cantidadOriginal}</span>
              <button style={styles.stepperButton} onClick={() => setCantidadOriginal((q) => Math.min(original.stock, q + 1))}><Plus size={14} /></button>
            </div>
            <span style={{ fontSize: 12, color: "#A68A68" }}>({original.stock} en stock)</span>
          </div>
        )}

        {tipo === "cambio" && (
          <>
            <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 8 }}>Producto de reemplazo</div>
            {reemplazo ? (
              <div style={{ ...styles.selectRow, marginBottom: 14 }}>
                <span>{reemplazo.nombre}</span>
                <button style={{ ...styles.iconButton, marginLeft: 12 }} onClick={() => setReemplazo(null)} aria-label="Cambiar selección">
                  <X size={14} />
                </button>
              </div>
            ) : (
              <div style={{ marginBottom: 14 }}>
                <BuscadorProducto
                  products={products}
                  query={queryReemplazo}
                  setQuery={setQueryReemplazo}
                  onSelect={(p) => { setReemplazo(p); setCantidadReemplazo(1); }}
                  placeholder="Buscar producto de reemplazo"
                />
              </div>
            )}
            {reemplazo && (
              <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 18 }}>
                <span style={{ fontSize: 13, color: "#8A6F52" }}>Cantidad</span>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <button style={styles.stepperButton} onClick={() => setCantidadReemplazo((q) => Math.max(1, q - 1))}><Minus size={14} /></button>
                  <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 16, minWidth: 24, textAlign: "center" }}>{cantidadReemplazo}</span>
                  <button style={styles.stepperButton} onClick={() => setCantidadReemplazo((q) => Math.min(reemplazo.stock, q + 1))}><Plus size={14} /></button>
                </div>
                <span style={{ fontSize: 12, color: "#A68A68" }}>({reemplazo.stock} en stock)</span>
              </div>
            )}
          </>
        )}

        <div style={{ marginBottom: 18 }}>
          <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, color: "#8A6F52", marginBottom: 6 }}>
            <MessageSquare size={14} /> Comentario / motivo
          </label>
          <textarea
            value={comentario}
            onChange={(e) => setComentario(e.target.value)}
            placeholder={tipo === "cambio" ? "Ej: pico roto, cliente lo trajo de vuelta" : "Ej: se cayó del estante, base rajada"}
            rows={3}
            style={{ ...styles.input, resize: "vertical", fontFamily: "inherit" }}
          />
        </div>

        <button style={{ ...styles.primaryButton, opacity: puedeConfirmar ? 1 : 0.5 }} disabled={!puedeConfirmar} onClick={confirmar}>
          <Check size={16} /> {tipo === "cambio" ? "Registrar cambio" : "Registrar baja"}
        </button>

        {mensaje && (
          <div style={{
            marginTop: 16, padding: "10px 12px", borderRadius: 8, fontSize: 13,
            background: "#F6E7D3", color: "#A8754E"
          }}>
            {mensaje.text}
          </div>
        )}
      </div>

      {historial.length > 0 && (
        <div style={{ marginTop: 24 }}>
          <div style={{ fontWeight: 700, marginBottom: 10, fontSize: 14 }}>Últimos movimientos</div>
          <div style={styles.tableWrap}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Tipo</th>
                  <th style={styles.th}>Detalle</th>
                  <th style={styles.th}>Comentario</th>
                  <th style={styles.th}>Fecha</th>
                </tr>
              </thead>
              <tbody>
                {historial.map((a) => (
                  <tr key={a.id} className="fila-tabla">
                    <td style={styles.td}>
                      <span style={{
                        fontSize: 12, fontWeight: 700, padding: "3px 8px", borderRadius: 20,
                        background: a.tipo === "cambio" ? "#F6E7D3" : "#FBEAE9",
                        color: a.tipo === "cambio" ? "#A8754E" : "#B23A34"
                      }}>
                        {a.tipo === "cambio" ? "Cambio" : "Baja"}
                      </span>
                    </td>
                    <td style={styles.td}>
                      {a.tipo === "cambio"
                        ? `${a.cantidadOriginal} × ${a.productoOriginalNombre} → ${a.cantidadReemplazo} × ${a.productoReemplazoNombre}`
                        : `${a.cantidadOriginal} × ${a.productoOriginalNombre}`}
                    </td>
                    <td style={{ ...styles.td, color: "#8A6F52", fontSize: 13 }}>{a.comentario || "—"}</td>
                    <td style={{ ...styles.td, color: "#8A6F52", fontSize: 12.5 }}>{new Date(a.fecha).toLocaleString("es-AR")}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

function ListaPrecios({ products }) {
  const ordenados = useMemo(
    () => [...products].sort((a, b) => a.nombre.localeCompare(b.nombre)),
    [products]
  );

  return (
    <div className="imprimir-full">
      <div className="no-imprimir">
        <PageHeader
          title="Lista de precios"
          subtitle="Ordenada por nombre, lista para imprimir"
          action={
            <button style={styles.primaryButton} onClick={() => window.print()}>
              <Printer size={16} /> Imprimir
            </button>
          }
        />
      </div>

      {products.length === 0 ? (
        <EmptyState title="No hay productos para mostrar" detail="Cargá productos en el inventario para generar la lista." />
      ) : (
        <table style={styles.table}>
          <tbody>
            {ordenados.map((p) => (
              <tr key={p.id}>
                <td style={{ ...styles.td, paddingLeft: 0 }}>{p.nombre}</td>
                <td style={{ ...styles.td, textAlign: "right", paddingRight: 0, fontFamily: "'JetBrains Mono', monospace", fontWeight: 600 }}>
                  ${money(p.precio)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

function toDateInputValue(date) {
  return date.toISOString().slice(0, 10);
}

function Estadisticas({ products, sales, ajustes }) {
  const [desde, setDesde] = useState(() => {
    const d = new Date();
    d.setDate(d.getDate() - 30);
    return toDateInputValue(d);
  });
  const [hasta, setHasta] = useState(() => toDateInputValue(new Date()));

  const enRango = (isoDate) => {
    if (!isoDate) return false;
    const t = new Date(isoDate).getTime();
    const desdeMs = new Date(desde + "T00:00:00").getTime();
    const hastaMs = new Date(hasta + "T23:59:59").getTime();
    return t >= desdeMs && t <= hastaMs;
  };

  const productosCargados = useMemo(
    () => products.filter((p) => enRango(p.creadoEn)).sort((a, b) => new Date(b.creadoEn) - new Date(a.creadoEn)),
    [products, desde, hasta]
  );
  const ventasEnRango = useMemo(
    () => sales.filter((s) => enRango(s.fecha)).sort((a, b) => new Date(b.fecha) - new Date(a.fecha)),
    [sales, desde, hasta]
  );

  const unidadesVendidas = ventasEnRango.reduce((sum, s) => sum + s.cantidad, 0);
  const totalFacturado = ventasEnRango.reduce((sum, s) => sum + s.total, 0);
  const totalCosto = ventasEnRango.reduce((sum, s) => sum + (s.costoUnitario || 0) * s.cantidad, 0);
  const ganancia = totalFacturado - totalCosto;

  const ajustesEnRango = useMemo(
    () => ajustes.filter((a) => enRango(a.fecha)).sort((a, b) => new Date(b.fecha) - new Date(a.fecha)),
    [ajustes, desde, hasta]
  );
  const unidadesDadasDeBaja = ajustesEnRango.reduce((sum, a) => sum + a.cantidadOriginal, 0);

  return (
    <div>
      <PageHeader title="Estadísticas" subtitle="Elegí un rango de fechas para ver la actividad del negocio" />

      <div style={{ ...styles.panel, display: "flex", gap: 16, flexWrap: "wrap", alignItems: "flex-end", marginBottom: 20 }}>
        <Field label="Desde" style={{ marginBottom: 0 }}>
          <input type="date" value={desde} max={hasta} onChange={(e) => setDesde(e.target.value)} style={styles.input} />
        </Field>
        <Field label="Hasta" style={{ marginBottom: 0 }}>
          <input type="date" value={hasta} min={desde} onChange={(e) => setHasta(e.target.value)} style={styles.input} />
        </Field>
      </div>

      <div style={styles.statGrid}>
        <StatBlock label="Productos cargados" value={productosCargados.length} />
        <StatBlock label="Unidades vendidas" value={unidadesVendidas} />
        <StatBlock label="Total facturado" value={`$${money(totalFacturado)}`} mono />
        <StatBlock label="Ganancia estimada" value={`$${money(ganancia)}`} mono />
        <StatBlock label="Unidades dadas de baja" value={unidadesDadasDeBaja} />
      </div>

      <div style={{ marginTop: 24 }}>
        <div style={{ fontWeight: 700, marginBottom: 10, fontSize: 14 }}>Productos cargados en el período</div>
        {productosCargados.length === 0 ? (
          <EmptyState title="Sin altas de inventario en este rango" detail="No se cargaron productos nuevos entre esas fechas." />
        ) : (
          <div style={styles.tableWrap}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Producto</th>
                  <th style={{ ...styles.th, textAlign: "right" }}>Precio</th>
                  <th style={{ ...styles.th, textAlign: "right" }}>Stock actual</th>
                  <th style={styles.th}>Fecha de carga</th>
                </tr>
              </thead>
              <tbody>
                {productosCargados.map((p) => (
                  <tr key={p.id} className="fila-tabla">
                    <td style={styles.td}>{p.nombre}</td>
                    <td style={{ ...styles.td, textAlign: "right", fontFamily: "'JetBrains Mono', monospace" }}>${money(p.precio)}</td>
                    <td style={{ ...styles.td, textAlign: "right", fontFamily: "'JetBrains Mono', monospace" }}>{p.stock}</td>
                    <td style={{ ...styles.td, color: "#8A6F52", fontSize: 12.5 }}>{new Date(p.creadoEn).toLocaleDateString("es-AR")}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <div style={{ marginTop: 28 }}>
        <div style={{ fontWeight: 700, marginBottom: 10, fontSize: 14 }}>Ventas generadas en el período</div>
        {ventasEnRango.length === 0 ? (
          <EmptyState title="Sin ventas en este rango" detail="No se registraron ventas entre esas fechas." />
        ) : (
          <div style={styles.tableWrap}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Producto</th>
                  <th style={{ ...styles.th, textAlign: "right" }}>Cant.</th>
                  <th style={{ ...styles.th, textAlign: "right" }}>Total</th>
                  <th style={styles.th}>Fecha</th>
                </tr>
              </thead>
              <tbody>
                {ventasEnRango.map((s) => (
                  <tr key={s.id} className="fila-tabla">
                    <td style={styles.td}>{s.nombre}</td>
                    <td style={{ ...styles.td, textAlign: "right", fontFamily: "'JetBrains Mono', monospace" }}>{s.cantidad}</td>
                    <td style={{ ...styles.td, textAlign: "right", fontFamily: "'JetBrains Mono', monospace" }}>${money(s.total)}</td>
                    <td style={{ ...styles.td, color: "#8A6F52", fontSize: 12.5 }}>{new Date(s.fecha).toLocaleString("es-AR")}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
      <div style={{ marginTop: 28 }}>
        <div style={{ fontWeight: 700, marginBottom: 10, fontSize: 14 }}>Cambios y bajas en el período</div>
        {ajustesEnRango.length === 0 ? (
          <EmptyState title="Sin cambios ni bajas en este rango" detail="No se registraron roturas, fallas o cambios entre esas fechas." />
        ) : (
          <div style={styles.tableWrap}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Tipo</th>
                  <th style={styles.th}>Detalle</th>
                  <th style={styles.th}>Comentario</th>
                  <th style={styles.th}>Fecha</th>
                </tr>
              </thead>
              <tbody>
                {ajustesEnRango.map((a) => (
                  <tr key={a.id} className="fila-tabla">
                    <td style={styles.td}>
                      <span style={{
                        fontSize: 12, fontWeight: 700, padding: "3px 8px", borderRadius: 20,
                        background: a.tipo === "cambio" ? "#F6E7D3" : "#FBEAE9",
                        color: a.tipo === "cambio" ? "#A8754E" : "#B23A34"
                      }}>
                        {a.tipo === "cambio" ? "Cambio" : "Baja"}
                      </span>
                    </td>
                    <td style={styles.td}>
                      {a.tipo === "cambio"
                        ? `${a.cantidadOriginal} × ${a.productoOriginalNombre} → ${a.cantidadReemplazo} × ${a.productoReemplazoNombre}`
                        : `${a.cantidadOriginal} × ${a.productoOriginalNombre}`}
                    </td>
                    <td style={{ ...styles.td, color: "#8A6F52", fontSize: 13 }}>{a.comentario || "—"}</td>
                    <td style={{ ...styles.td, color: "#8A6F52", fontSize: 12.5 }}>{new Date(a.fecha).toLocaleString("es-AR")}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

function PageHeader({ title, subtitle, action }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 22, flexWrap: "wrap", gap: 12 }}>
      <div>
        <h1 style={{ margin: 0, fontSize: 24, fontWeight: 800 }}>{title}</h1>
        {subtitle && <div style={{ color: "#8A6F52", fontSize: 14, marginTop: 4 }}>{subtitle}</div>}
      </div>
      {action}
    </div>
  );
}

function Field({ label, children, style }) {
  return (
    <div style={{ marginBottom: 16, ...style }}>
      <label style={{ display: "block", fontSize: 13, color: "#8A6F52", marginBottom: 6 }}>{label}</label>
      {children}
    </div>
  );
}

function EmptyState({ title, detail }) {
  return (
    <div style={{ border: "1px dashed #D8C3A5", borderRadius: 4, padding: "40px 20px", textAlign: "center" }}>
      <div style={{ fontWeight: 700, marginBottom: 6 }}>{title}</div>
      <div style={{ color: "#8A6F52", fontSize: 14 }}>{detail}</div>
    </div>
  );
}

function ConfirmModal({ text, onCancel, onConfirm }) {
  return (
    <div style={styles.modalOverlay} onClick={onCancel}>
      <div style={styles.modalBox} onClick={(e) => e.stopPropagation()}>
        <div style={{ marginBottom: 18, fontSize: 14 }}>{text}</div>
        <div style={{ display: "flex", gap: 10, justifyContent: "flex-end" }}>
          <button style={styles.ghostButton} onClick={onCancel}>Cancelar</button>
          <button
            style={{ ...styles.primaryButton, backgroundImage: "none", background: "#B23A34", boxShadow: "0 3px 10px rgba(178,58,52,0.3)" }}
            onClick={onConfirm}
          >
            Eliminar
          </button>
        </div>
      </div>
    </div>
  );
}

